/**
 * @summary Log out another device (API-AUTH-15)
 */
export const revokeSession = (
  sessionId: string,
  options?: SecondParameter<typeof httpClient>,
  signal?: AbortSignal,
) => {
  return httpClient<void>(
    { url: `/api/v1/auth/sessions/${sessionId}`, method: 'DELETE', signal },
    options,
  )
}

